    'migrates a stable v2 %s state to v3 without changing its phase or revision',
    async (phase) => {
      const name = `v2-${phase}`;
      const { changeDir, state } = await seedCurrentPhase(name, phase);
      await downgradeToV2(state);

      const migrated = await migrateNativeChange({
        paths,
