    expect(confirmed.change.approved_contract_hash).toMatch(/^[a-f0-9]{64}$/u);
    expect(confirmed.change.approved_contract_hash).not.toBe(approvedHash);
    const scope = await readNativeImplementationScopeBundle(
      paths,
